def paare():
    """Abschnitt.Schluessel -> [deutsch, englisch]; Posten 'e' (je Sprache einzeln) werden
    zusammengefuehrt. Doppelte Vergabe je Sprache steht in der Liste der Fehler."""
    aus, fehler, abschnitt = {}, [], ''
    for x in INHALT:
        if x[0] == 'a':
            abschnitt = x[1]
            if abschnitt == 'ANSAGE':
                fehler.append('[ANSAGE] steht in der Tabelle - er kommt aus gemeinsam_pruefen.py')
        elif x[0] in ('s', 'e'):
            voll = '%s.%s' % (abschnitt, x[1] if x[0] == 's' else x[2])
            w = aus.setdefault(voll, [None, None])
            for sp, wert in ((0, x[2]), (1, x[3])) if x[0] == 's' else (((0 if x[1] == 'de' else 1), x[3]),):
                if w[sp] is not None:
                    fehler.append('%s: doppelt vergeben' % voll)
                w[sp] = wert
    for voll, w in aus.items():
        if None in w:
            fehler.append('%s: steht nur in einer Sprache' % voll)
    return aus, fehler


def pruefe_werte():
    alle, fehler = paare()
    for voll, (de, en) in sorted(alle.items()):
        if de is None or en is None:
            continue
        abschnitt = voll.split('.')[0]
        for name, w in (('DE', de), ('EN', en)):
            if '"' in w:
                fehler.append('%s (%s): gerades Anfuehrungszeichen im Wert' % (voll, name))
            if '\r' in w or '\n' in w:
                fehler.append('%s (%s): Zeilenumbruch im Wert' % (voll, name))
            if abschnitt in ROH_VERBOTEN and re.search(r'&[a-zA-Z]+;|&#\d+;|<[a-z/]', w):
                fehler.append('%s (%s): Auszeichnung in einem maskierten Abschnitt' % (voll, name))
        if len(re.findall(r'%[sd]', de)) != len(re.findall(r'%[sd]', en)):
            fehler.append('%s: verschieden viele Platzhalter (DE %d, EN %d)'
                          % (voll, len(re.findall(r'%[sd]', de)), len(re.findall(r'%[sd]', en))))
    return fehler


def ini_text(sprache):
    """Die vollstaendige .ini einer Sprache (LF), [ANSAGE] aus der Quelle des Sprachmoduls."""
    import gemeinsam_pruefen
    sp = 0 if sprache == 'de' else 1
    z = list(KOPF[sprache])
    for x in INHALT:
        if x[0] == 'a':
            z.append('[%s]' % x[1])
        elif x[0] == 'l':
            z.append('')
        elif x[0] == 'k':
            z.extend(x[1 + sp])
        elif x[0] == 'e':
            if x[1] == sprache:
                z.append('%s = "%s"' % (x[2], x[3]))
        else:
            z.append('%s = "%s"' % (x[1], x[2 + sp]))
    return '\n'.join(z) + '\n' + gemeinsam_pruefen.ini_abschnitt(sprache)


# Wache gegen stillen Schluesselverlust - eine Quelle fuer alle Erzeuger
# (Werkzeuge/sprachwache.py): verschwaende ein Schluessel der vorhandenen .ini, bricht der
# Lauf mit Rueckgabewert 2 ab, BEVOR etwas geschrieben ist.
# Absichtlich loeschen:  SPRACHWACHE=aus python3 wi_sprache_erzeugen.py <ordner>
import sprachwache
sprachwache.einhaengen()


if __name__ == '__main__':
    fehler = pruefe_werte()
    if fehler:
        print('ABBRUCH - der Erzeuger weist ab statt zurechtzubiegen:')
        for f in fehler:
            print('  ' + f)
        sys.exit(1)
    print('%d Schluessel je Sprache (ohne [ANSAGE]); alle Werte geprueft.'
          % len(paare()[0]))
    if len(sys.argv) < 2:
        print('Kein Plugin-Ordner angegeben - es wurde nur geprueft.')
        sys.exit(0)
    ordner = sys.argv[1]
    for sp in ('de', 'en'):
        p = os.path.join(ordner, 'templates', 'lang', 'language_%s.ini' % sp)
        t = ini_text(sp)
        if '\r' in t:
            sys.exit('ABBRUCH: CR im erzeugten Text')
        if os.path.isfile(p) and b'\r\n' in open(p, 'rb').read():
            sys.exit('ABBRUCH %s: die vorhandene Datei traegt CRLF - die Linie fuehrt LF' % p)
        with open(p, 'wb') as fh:
            fh.write(t.encode('utf-8'))
        print('  %s: %d Zeilen geschrieben' % (os.path.basename(p), t.count('\n')))
